import os

_LUA_PATHS = ['resources/BK_Keywords/lua/']
_EXTERNAL_LIBS = ['resources.BK_Keywords.robot_egate_communicator.GenericEgateAggregator']


def generate_lua_paths():
    wd = os.path.dirname(os.path.abspath(__file__))
    robot_dir = os.path.dirname(os.path.dirname(wd))
    lua_paths = [os.path.join(robot_dir, lua_path) for lua_path in _LUA_PATHS]
    lua_paths.append(robot_dir)
    return lua_paths, _EXTERNAL_LIBS
